package com.pipican.client.boss;
import com.pipican.Pipican;import com.pipican.boss.SyltheraEntity;import net.minecraft.client.model.EntityModel;import net.minecraft.client.model.geom.ModelPart;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;import net.minecraft.resources.Identifier;import net.minecraft.util.Mth;
/** Blooming crown, staff, and robe poses for the preserved Sylthera model. */
public final class SyltheraRenderer extends MobRenderer<SyltheraEntity,SyltheraRenderer.State,SyltheraRenderer.Model>{public SyltheraRenderer(EntityRendererProvider.Context c){super(c,new Model(BossGeometry.load("sylthera_primordial_bloom")),1f);}public static final class State extends LivingEntityRenderState{int phase,action;float remaining,hurt;}@Override public State createRenderState(){return new State();}@Override public Identifier getTextureLocation(State s){return Pipican.id("textures/entity/boss/sylthera_"+(s.phase==2?"primordial":"bloom")+".png");}@Override public void extractRenderState(SyltheraEntity e,State s,float p){super.extractRenderState(e,s,p);s.phase=e.phase();s.action=e.syltheraAction();s.remaining=Math.max(0,e.abilityTicksRemaining()-p);s.hurt=e.hurtTime-p;}@Override protected net.minecraft.world.phys.AABB getBoundingBoxForCulling(SyltheraEntity e){return super.getBoundingBoxForCulling(e).inflate(1.25);}
 static final class Model extends EntityModel<State>{private final ModelPart body,head,leftArm,rightArm,leftLeg,rightLeg,leftCrest,rightCrest,robe,staff;Model(ModelPart r){super(r);var root=r.getChild("root");body=root.getChild("body");head=body.getChild("head");leftArm=body.getChild("left_arm");rightArm=body.getChild("right_arm");leftLeg=root.getChild("left_leg");rightLeg=root.getChild("right_leg");leftCrest=head.getChild("left_crest");rightCrest=head.getChild("right_crest");robe=root.getChild("robe");staff=rightArm.getChild("staff");}@Override public void setupAnim(State s){super.setupAnim(s);float gait=Mth.clamp(s.walkAnimationSpeed,0,1),sway=Mth.sin(s.ageInTicks*.12f),tell=1-Mth.clamp(s.remaining/60f,0,1);head.yRot=Mth.clamp(s.yRot,-32,32)*Mth.DEG_TO_RAD;head.xRot=Mth.clamp(s.xRot,-14,14)*Mth.DEG_TO_RAD;leftArm.xRot=Mth.cos(s.ageInTicks*.48f)*.28f*gait;rightArm.xRot=Mth.cos(s.ageInTicks*.48f+(float)Math.PI)*.28f*gait;leftLeg.xRot=Mth.cos(s.ageInTicks*.48f+(float)Math.PI)*.35f*gait;rightLeg.xRot=Mth.cos(s.ageInTicks*.48f)*.35f*gait;robe.zRot=sway*.018f;staff.zRot=-.04f+sway*.025f;leftCrest.zRot=-.08f+sway*.04f;rightCrest.zRot=.08f-sway*.04f;switch(s.action){case 1->{rightArm.xRot=-.7f*tell;}case 2->{leftArm.xRot=.35f*tell;rightArm.xRot=-.45f*tell;leftCrest.zRot=-.45f*tell;rightCrest.zRot=.45f*tell;}case 3->{leftArm.xRot=-.5f*tell;rightArm.xRot=-.5f*tell;staff.zRot=.32f*tell;}case 4->{head.xRot=-.15f*tell;leftCrest.zRot=-.3f*tell;rightCrest.zRot=.3f*tell;staff.zRot=-.24f*tell;}case 5->{leftCrest.zRot=-.5f;rightCrest.zRot=.5f;robe.zRot=.08f;}case 6->{leftArm.xRot=-.35f;rightArm.xRot=-.35f;leftCrest.zRot=-.25f;rightCrest.zRot=.25f;}default->{}}if(s.phase==2){leftCrest.zRot+=sway*.08f;rightCrest.zRot-=sway*.08f;}if(s.hurt>0)body.zRot=.04f*Mth.sin(s.hurt*1.5f);if(s.deathTime>0)body.xRot=.68f;}}
}
